using Confectory.Core;
using System.Text.Json.Nodes;
namespace Confectory.Tests;
public sealed class RefNodeTests : TestCase
{
    const string Feature="function Api::Value (int n,out int count) -> int {}";
    const string Mutate="a=10;b+=a;audit=a+b;return a+b+audit;";
    static Parameter Arg(string type,string name,string? mode=null)=>new(type,name,mode);
    static FunctionSignature Signature(string result,params Parameter[] args)=>new(args.ToList(),result);
    static JsonObject Bind(string key,string value)=>new(){[key]=value};
    static JsonObject Result(string node,string output)=>new(){["node"]=node,["output"]=output};
    static JsonObject Edge(string from,string to,string port="next")=>new(){["from"]=from,["port"]=port,["to"]=to};
    static JsonObject Local(string id,string type,JsonNode initial)=>new(){["id"]=id,["name"]=id,["type"]=type,["initial"]=new JsonObject{["constant"]=initial}};
    static JsonObject Graph()=>new(){["schema"]=1,["profile"]=FeatureBlueprint.RefNodesProfile,["feature"]="Api::Value",["contractHash"]=FeatureBlueprint.ContractHash(new Parser(Feature,"<ref>").ParseElement()),["entry"]="mutate",["locals"]=new JsonArray(Local("cell","int",JsonValue.Create(5)!)),["nodes"]=new JsonArray(),["edges"]=new JsonArray(),["exits"]=new JsonObject()};
    static JsonObject Code(string id,FunctionSignature sig)=>new(){["id"]=id,["kind"]="code",["intent"]="Compute "+id,["control"]="next",["signature"]=FeatureBlueprint.SignatureDocument(sig),["arguments"]=new JsonObject(),["implementation"]=id+".node.json"};
    static JsonObject Export(string name,JsonNode value)=>new(){["id"]="publish_"+name,["kind"]="export",["intent"]="Assign "+name,["control"]="next",["output"]=name,["signature"]=FeatureBlueprint.SignatureDocument(Signature("void",Arg("int","value"))),["arguments"]=new JsonObject{["value"]=value}};
    static FunctionSignature MutateSignature()=>Signature("int",Arg("int","a","ref"),Arg("int","b","ref"),Arg("int","audit","out"));
    static JsonObject Query(JsonObject graph,string operation="featureBlueprintDescribe",JsonObject? records=null,JsonObject? contracts=null)=>FeatureBlueprint.Execute(new JsonObject{["operation"]=operation,["featureSource"]=Feature,["graph"]=graph.DeepClone(),["implementations"]=records?.DeepClone(),["featureContracts"]=contracts?.DeepClone()});
    JsonObject Write(JsonObject graph,Dictionary<string,string> bodies,string imports="",JsonObject? contracts=null)
    {
        var defs=Query(graph,"featureBlueprintNodes",contracts:contracts);Equal("node-definitions",Text(defs,"state"));var records=new JsonObject();foreach(var item in bodies){var node=defs["nodes"]!.AsArray().Single(n=>n!["id"]!.ToString()==item.Key)!;var record=new JsonObject{["schema"]=1,["node"]=item.Key,["definitionHash"]=node["definitionHash"]!.DeepClone(),["source"]=item.Value};records[item.Key]=record;f.Body("Provider",item.Key+".node.json",record.ToJsonString());}
        f.Add("Api","function","Value",Feature);f.Add("Provider","implementation","ValueBody","implementation Provider::ValueBody for Api::Value (int original,out int result) -> int {"+imports+"blueprint common \"ref.graph.json\";}");f.Body("Provider","ref.graph.json",graph.ToJsonString());f.Add("App","implementation","MainBody","implementation App::MainBody for App::Main () -> int {import Api::Value as Value (int,out int) -> int;body common \"main.csbody\";}");f.Sync();return records;
    }
    static void Outputs(JsonObject graph,JsonNode value,JsonNode count){graph["nodes"]!.AsArray().Add(Export("return",value));graph["nodes"]!.AsArray().Add(Export("count",count));graph["edges"]!.AsArray().Add(Edge("mutate","publish_return"));graph["edges"]!.AsArray().Add(Edge("publish_return","publish_count"));}
    public void test_ordinary_csharp_ref_calls_preserve_same_slot_aliases_including_ref_out_same_caller_cell()
    {
        f.Add("Api","function","Value","function Api::Value (ref int x,ref int y,out int value) -> int {}");f.Add("Provider","implementation","ValueBody","implementation Provider::ValueBody for Api::Value (ref int a,ref int b,out int audit) -> int {body common \"value.csbody\";}");f.Body("Provider","value.csbody",Mutate);f.Add("App","implementation","MainBody","implementation App::MainBody for App::Main () -> int {import Api::Value as Value (ref int,ref int,out int) -> int;body common \"main.csbody\";}");f.Body("App","main.csbody","int n=5;int value=calls.Value.Invoke(ref n,ref n,out int audit);Console.WriteLine(value+\",\"+n+\",\"+audit);n=5;value=calls.Value.Invoke(ref n,ref n,out n);Console.WriteLine(value+\",\"+n);return 0;");f.Sync();Output(Build(),"80,20,40\n120,40");
        var plain=new Parser("function Api::Plain (int n) -> int {}","<plain>").ParseElement();var doc=FeatureBlueprint.SignatureDocument(new Parser("function Api::Ref (ref int n) -> int {}","<ref>").ParseElement().Signature!);Equal("ref",doc["args"]![0]!["mode"]!.ToString());True(!plain.Signature!.Matches(new Parser("function Api::Plain (ref int n) -> int {}","<ref>").ParseElement().Signature));
        var refused=FeatureBlueprint.Execute(new JsonObject{["operation"]="featureBlueprintDescribe",["featureSource"]="function Api::Value (ref int x,ref int y,out int value) -> int {}",["graph"]=Graph()});Equal("GRAPH_REF_FEATURE_UNSUPPORTED",Text(refused["diagnostics"]![0]!,"code"));
    }
    public void test_code_ref_arguments_alias_same_local_immediately_and_out_warning_remains_per_end()
    {
        var g=Graph();var mutate=Code("mutate",MutateSignature());mutate["arguments"]=new JsonObject{["a"]=Bind("local","cell"),["b"]=Bind("local","cell")};var choose=Code("choose",Signature("bool",Arg("int","n")));choose["control"]="branch";choose["arguments"]=new JsonObject{["n"]=Bind("input","n")};g["nodes"]=new JsonArray(choose,mutate);g["entry"]="choose";Outputs(g,Result("mutate","return"),Bind("local","cell"));g["edges"]!.AsArray().Add(Edge("choose","mutate","true"));var records=Write(g,new(){{"mutate",Mutate},{"choose","return n>0;"}});var described=Query(g,records:records);Equal("choose/false",Text(described["warnings"]![0]!,"subject"));Equal(2,described["warnings"]![0]!["missingOutputs"]!.AsArray().Count);f.Body("App","main.csbody","foreach(int n in new[]{1,-1,1}){int value=calls.Value.Invoke(n,out int count);Console.WriteLine(value+\",\"+count);}return 0;");Output(Build(),"80,20\n0,0\n80,20");var proof=new Builder(f.Project,"portable").CheckBlueprintNode("Provider::ValueBody","common","mutate");True(proof["compiled"]!.GetValue<bool>()&&!proof["executed"]!.GetValue<bool>());
        var bad=g.DeepClone().AsObject();bad["profile"]=FeatureBlueprint.LocalsProfile;Equal("GRAPH_REF_PROFILE",Text(Query(bad)["diagnostics"]![0]!,"code"));bad=g.DeepClone().AsObject();bad["nodes"]![1]!["arguments"]!["a"]=new JsonObject{["constant"]=5};Equal("GRAPH_REF_STORAGE",Text(Query(bad,records:records)["diagnostics"]![0]!,"code"));
    }
    public void test_ref_to_value_input_and_preceding_node_result_use_real_storage_without_caller_copyback()
    {
        var g=Graph();var m=Code("mutate",MutateSignature());m["arguments"]=new JsonObject{["a"]=Bind("input","n"),["b"]=Bind("input","n")};g["nodes"]=new JsonArray(m);Outputs(g,Result("mutate","return"),Bind("input","n"));Write(g,new(){{"mutate",Mutate}});f.Body("App","main.csbody","int n=5;int value=calls.Value.Invoke(n,out int count);Console.WriteLine(value+\",\"+count+\",\"+n);return 0;");Output(Build(),"80,20,5");
        var seed=Code("seed",Signature("int",Arg("int","n")));seed["arguments"]=new JsonObject{["n"]=Bind("input","n")};g["nodes"]!.AsArray().Insert(0,seed);g["entry"]="seed";g["edges"]!.AsArray().Insert(0,Edge("seed","mutate"));m["arguments"]=new JsonObject{["a"]=Bind("node","seed"),["b"]=Bind("node","seed")};g["nodes"]![2]!["arguments"]!["value"]=Bind("node","seed");g["nodes"]![3]!["arguments"]!["value"]=Result("mutate","audit");Write(g,new(){{"mutate",Mutate},{"seed","return n+1;"}});f.Body("App","main.csbody","int value=calls.Value.Invoke(5,out int count);Console.WriteLine(value+\",\"+count);return 0;");Output(Build(),"20,40");
    }
    public void test_typed_ref_call_uses_selected_object_scope_and_real_aliases()
    {
        const string callee="function Api::Mutate (ref int first,ref int second,out int sum) -> int {}";f.Add("Api","function","Mutate",callee);f.Add("Provider","implementation","MutateBody","implementation Provider::MutateBody for Api::Mutate (ref int a,ref int b,out int audit) -> int {body common \"mutate.csbody\";}");f.Body("Provider","mutate.csbody",Mutate);f.Add("Provider","implementation","WrongBody","implementation Provider::WrongBody for Api::Mutate (ref int a,ref int b,out int audit) -> int {body common \"wrong.csbody\";}");f.Body("Provider","wrong.csbody","a=99;b=99;audit=99;return 99;");f.Add("Provider","object","Selected","object Provider::Selected {provide Api::Mutate with Provider::MutateBody;}");f.Main("provide Api::Value with Provider::ValueBody;provide Api::Mutate with Provider::WrongBody;");var sig=new Parser(callee,"<callee>").ParseElement().Signature!;var call=Code("mutate",sig);call["kind"]="call";call.Remove("implementation");call["feature"]="Api::Mutate";call["arguments"]=new JsonObject{["first"]=Bind("local","cell"),["second"]=Bind("local","cell")};var g=Graph();g["nodes"]=new JsonArray(call);Outputs(g,Result("mutate","return"),Bind("local","cell"));string alias=FeatureBlueprint.ImportAlias("Api::Mutate");Write(g,new(),"import Api::Mutate as "+alias+" (ref int,ref int,out int) -> int in Provider::Selected;",new JsonObject{["Api::Mutate"]=callee});f.Body("App","main.csbody","int value=calls.Value.Invoke(1,out int count);Console.WriteLine(value+\",\"+count);return 0;");Output(Build(),"80,20");
    }
    public void test_ref_array_parameters_alias_the_reference_slot_when_replacing_the_array()
    {
        var g=Graph();g["locals"]=new JsonArray(Local("items","int[]",new JsonArray(1)));var swap=Code("mutate",Signature("int",Arg("int[]","a","ref"),Arg("int[]","b","ref")));swap["arguments"]=new JsonObject{["a"]=Bind("local","items"),["b"]=Bind("local","items")};var read=Code("read",Signature("int",Arg("int[]","items")));read["arguments"]=new JsonObject{["items"]=Bind("local","items")};g["nodes"]=new JsonArray(swap,read,Export("return",Result("mutate","return")),Export("count",Result("read","return")));g["edges"]=new JsonArray(Edge("mutate","read"),Edge("read","publish_return"),Edge("publish_return","publish_count"));Write(g,new(){{"mutate","a=new[]{10};b[0]+=a[0];return a[0]+b[0];"},{"read","return items[0];"}});f.Body("App","main.csbody","for(int i=0;i<2;i++){int value=calls.Value.Invoke(1,out int count);Console.WriteLine(value+\",\"+count);}return 0;");Output(Build(),"40,20\n40,20");
    }

}
